 function change(next:Flow){if(next.intentReview&&JSON.stringify([next.nodes.map(n=>[n.id,n.name,n.type,n.parameters,n.credentialId]),next.connections])!==JSON.stringify([flowRef.current.nodes.map(n=>[n.id,n.name,n.type,n.parameters,n.credentialId]),flowRef.current.connections]))next={...next,intentReview:{...next.intentReview,reviewed:false}};next={...next,active:false};delete next.schedule;setPast(p=>[...p.slice(-39),clone(flowRef.current)]);setFuture([]);setFlow(next);flowRef.current=next;setDirty(true);setExecution(null);}
