 function addNode(id:string){const info=catalog.find(c=>c.id===id)!;if(info.category==='시작'){const existing=flow.nodes.find(n=>nodeInfo(n)?.category==='시작');if(existing){let startName=info.name;let suffix=2;while(flow.nodes.some(n=>n.id!==existing.id&&n.name===startName))startName=info.name+' '+suffix++;const next=renameNode(flow,existing.id,startName);const node={...existing,name:startName,type:info.n8nType,typeVersion:info.typeVersion,parameters:clone(info.parameters)};next.nodes=next.nodes.map(n=>n.id===existing.id?node:n);change(next);setSelected(node);setNodeOpen(true);toast('시작 방식을 바꿨어요. 연결된 다음 단계는 그대로 이어져요.');return;}}const next=clone(flow);let name=info.name;let number=2;while(next.nodes.some(n=>n.name===name))name=info.name+' '+number++;const last=next.nodes.findLast(n=>n.type!=='n8n-nodes-base.stickyNote');const note=info.n8nType==='n8n-nodes-base.stickyNote';const node:FlowNode={id:crypto.randomUUID(),name,type:info.n8nType,typeVersion:info.typeVersion,position:last?(note?[last.position[0],last.position[1]-240]:[last.position[0]+225,last.position[1]]):[150,325],parameters:clone(info.parameters)};next.nodes.push(node);if(last&&!note&&nodePorts(last).outputs.length){next.connections[last.name]??={main:[]};const output=last.type==='n8n-nodes-base.splitInBatches'?1:0;next.connections[last.name].main[output]??=[];next.connections[last.name].main[output].push({node:name,type:'main',index:0});}change(next);setSelected(node);setNodeOpen(true);}
